package com.ecommerce.cart.model;
import org.springframework.data.annotation.Id; import org.springframework.data.mongodb.core.mapping.Document; import java.time.Instant; import java.util.*;
@Document("carts") public class Cart { @Id private String id; private String userId; private List<Item> items=new ArrayList<>(); private Instant updatedAt=Instant.now(); public Cart(){} public Cart(String u){userId=u;} public String getId(){return id;} public void setId(String v){id=v;} public String getUserId(){return userId;} public void setUserId(String v){userId=v;} public List<Item> getItems(){return items;} public void setItems(List<Item> v){items=v==null?new ArrayList<>():v;} public Instant getUpdatedAt(){return updatedAt;} public void setUpdatedAt(Instant v){updatedAt=v;} }